-- Origin SQL:
SYSTEM FLUSH LOGS;
SYSTEM FLUSH LOGS query_log;
SYSTEM FLUSH LOGS query_log, system.part_log;
SYSTEM FLUSH LOGS ON CLUSTER c query_log;
SYSTEM FLUSH DISTRIBUTED t;
SYSTEM FLUSH DISTRIBUTED db.t;
SYSTEM FLUSH DISTRIBUTED ON CLUSTER c db.t;
SYSTEM FLUSH DISTRIBUTED db.t ON CLUSTER 'c';
SYSTEM FLUSH DISTRIBUTED db.t SETTINGS a = 1, b = 2;
SYSTEM FLUSH ASYNC INSERT QUEUE;
SYSTEM FLUSH ASYNC INSERT QUEUE ON CLUSTER c;
SYSTEM FLUSH ASYNC INSERT QUEUE db.t, db.u;


-- Format SQL:
SYSTEM FLUSH LOGS;
SYSTEM FLUSH LOGS query_log;
SYSTEM FLUSH LOGS query_log, system.part_log;
SYSTEM FLUSH LOGS ON CLUSTER c query_log;
SYSTEM FLUSH DISTRIBUTED t;
SYSTEM FLUSH DISTRIBUTED db.t;
SYSTEM FLUSH DISTRIBUTED ON CLUSTER c db.t;
SYSTEM FLUSH DISTRIBUTED ON CLUSTER 'c' db.t;
SYSTEM FLUSH DISTRIBUTED db.t SETTINGS a=1, b=2;
SYSTEM FLUSH ASYNC INSERT QUEUE;
SYSTEM FLUSH ASYNC INSERT QUEUE ON CLUSTER c;
SYSTEM FLUSH ASYNC INSERT QUEUE db.t, db.u;
